sys_script_include.script:
var Invoice = Class.create();
Invoice.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	/**
     * Reference Qualifier for 'appointment' field on Invoice table.
     * Condition: 
     * - Matches current invoice's patient (`appointment.patient = current.patient`).
     * - Matches current invoice's hospital (`appointment.hospital = current.hospital`).
     */
    getAppointmentRefQual: function(current) {
        if (!current) return '';

        var currentPatient = current.getValue('patient');
        var currentHospital = current.getValue('hospital');

        // Agar patient ya hospital select nahi hai, toh koi appointment show mat karo
        if (!currentPatient || !currentHospital) {
            return 'sys_id=00000000000000000000000000000000';
        }

        var appointmentSysids = [];
        var appointmentGr = new GlideRecord('x_2223823_apollo_0_appointment'); 

        appointmentGr.addQuery('patient', currentPatient);
        appointmentGr.addQuery('hospital', currentHospital);
        appointmentGr.query();

        while (appointmentGr.next()) {
            appointmentSysids.push(appointmentGr.getUniqueValue());
        }

        // Final Encoded Query return karo
        if (appointmentSysids.length > 0) {
            return 'sys_idIN' + appointmentSysids.join(',');
        } else {
            // Agar koi matching appointment nahi mili
            return 'sys_id=00000000000000000000000000000000';
        }
    },

    type: 'Invoice'
});
